/test/buffer.test.ts.content:
import assert from "node:assert/strict";
import { test } from "node:test";
import { MetricsBuffer } from "../src/metrics/buffer";

test("drops the oldest sample at capacity", () => {
  const buffer = new MetricsBuffer(2);
  buffer.push(1);
  buffer.push(2);
  buffer.push(3);
  assert.deepEqual(buffer.drain(), [2, 3]);
});

